//! Serialization of the complete WFP state owned by the Mullvad firewall.
//!
//! Every object is normalized so that the serialization is deterministic across
//! machines and runs:
//!
//! * objects are identified by their fixed GUIDs, or their GUID if unknown (the
//!   endpoint rules' keys are generated by the engine and vary per run, but they
//!   are stable within a dump since the whole line is sorted on),
//! * interface LUIDs are rendered as the interface alias they resolve to, and
//!   the tunnel interface as a placeholder, since the test picks whichever
//!   adapter the machine has,
//! * app paths have their volume number replaced, since it differs between
//!   boot cycles and machines,
//! * filters are sorted, as are the conditions within a filter: neither WFP
//!   nor the firewall semantics assign meaning to their order,
//! * the `filterId` (a runtime LUID) is omitted entirely.
//!
//! The WFP API hands out objects whose strings and condition values live in
//! engine-owned memory, valid only until `FwpmFreeMemory0`. Everything is
//! therefore deep-copied into owned types while that memory is alive, and
//! rendered afterwards from the copies.

use std::{
    fmt::Write as _,
    net::{Ipv4Addr, Ipv6Addr},
    ptr,
};

use windows_sys::Win32::Foundation::{ERROR_SUCCESS, HANDLE};
use windows_sys::Win32::NetworkManagement::IpHelper::ConvertInterfaceLuidToAlias;
use windows_sys::Win32::NetworkManagement::Ndis::NET_LUID_LH;
use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform::{
    FWP_ACTION_PERMIT, FWP_BYTE_BLOB_TYPE, FWP_EMPTY, FWP_RANGE_TYPE, FWP_SECURITY_DESCRIPTOR_TYPE,
    FWP_SID, FWP_TOKEN_ACCESS_INFORMATION_TYPE, FWP_TOKEN_INFORMATION_TYPE,
    FWP_UNICODE_STRING_TYPE, FWP_V4_ADDR_MASK, FWP_V6_ADDR_MASK, FWPM_FILTER0, FWPM_PROVIDER0,
    FWPM_SUBLAYER0, FwpmEngineClose0, FwpmEngineOpen0, FwpmFilterCreateEnumHandle0,
    FwpmFilterDestroyEnumHandle0, FwpmFilterEnum0, FwpmFreeMemory0, FwpmProviderCreateEnumHandle0,
    FwpmProviderDestroyEnumHandle0, FwpmProviderEnum0, FwpmSubLayerCreateEnumHandle0,
    FwpmSubLayerDestroyEnumHandle0, FwpmSubLayerEnum0,
};
use windows_sys::Win32::System::Rpc::RPC_C_AUTHN_DEFAULT;

use winfw::guids::{
    PROVIDER, PROVIDER_PERSISTENT, SUBLAYER_BASELINE, SUBLAYER_DNS, known_object_name,
};

// ---------------------------------------------------------------------------
// Owned copies of the WFP objects
// ---------------------------------------------------------------------------

#[derive(Clone)]
struct OwnedProvider {
    key: wfp::Guid,
    name: String,
    description: String,
    flags: u32,
}

#[derive(Clone)]
struct OwnedSublayer {
    key: wfp::Guid,
    name: String,
    description: String,
    weight: u16,
    flags: u32,
}

#[derive(Clone)]
struct OwnedFilter {
    key: wfp::Guid,
    name: String,
    description: String,
    layer: wfp::Guid,
    sublayer: wfp::Guid,
    provider: Option<wfp::Guid>,
    action: u32,
    flags: u32,
    weight: OwnedWeight,
    conditions: Vec<OwnedCondition>,
}

#[derive(Clone)]
struct OwnedCondition {
    field: wfp::Guid,
    match_type: i32,
    value: OwnedValue,
}

#[derive(Clone)]
enum OwnedWeight {
    Auto,
    Class(u8),
    RawU64(u64),
    RawU32(u32),
    Other(i32),
}

#[derive(Clone)]
enum OwnedValue {
    Empty,
    U8(u8),
    U16(u16),
    U32(u32),
    U64(u64),
    I8(i8),
    I16(i16),
    I32(i32),
    I64(i64),
    ByteArray16([u8; 16]),
    ByteBlob(Vec<u8>),
    V4Mask { addr: u32, mask: u32 },
    V6Mask { addr: [u8; 16], prefix: u8 },
    Range { low: OwnedScalar, high: OwnedScalar },
    UnicodeString(String),
    Opaque(&'static str),
    Unknown(i32),
}

#[derive(Clone)]
enum OwnedScalar {
    U8(u8),
    U16(u16),
    U32(u32),
    U64(u64),
    Unknown(i32),
}

/// Errors that can occur while dumping the WFP state.
#[derive(Debug)]
pub struct DumpError(pub u32);

impl std::fmt::Display for DumpError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "WFP serialization failed with error code {}", self.0)
    }
}

impl std::error::Error for DumpError {}

fn check(status: u32) -> Result<(), DumpError> {
    if status == ERROR_SUCCESS {
        Ok(())
    } else {
        Err(DumpError(status))
    }
}

// ---------------------------------------------------------------------------
// Dumping
// ---------------------------------------------------------------------------

/// Dump the current WFP state of the Mullvad firewall, as text.
pub fn dump() -> Result<String, DumpError> {
    let mut output = String::new();

    let providers = enumerate_providers()?;
    let sublayers = enumerate_sublayers()?;
    let filters = enumerate_filters()?;

    let mut ours: Vec<String> = providers
        .iter()
        .filter(|provider| provider.key == PROVIDER || provider.key == PROVIDER_PERSISTENT)
        .map(render_provider)
        .collect();
    ours.sort();
    writeln!(output, "providers: {}", ours.len()).unwrap();
    for provider in ours {
        output.push_str(&provider);
    }

    let mut ours: Vec<String> = sublayers
        .iter()
        .filter(|sublayer| sublayer.key == SUBLAYER_BASELINE || sublayer.key == SUBLAYER_DNS)
        .map(render_sublayer)
        .collect();
    ours.sort();
    writeln!(output, "sublayers: {}", ours.len()).unwrap();
    for sublayer in ours {
        output.push_str(&sublayer);
    }

    let mut ours: Vec<String> = filters
        .iter()
        .filter(|filter| {
            filter
                .provider
                .as_ref()
                .is_some_and(|provider| *provider == PROVIDER || *provider == PROVIDER_PERSISTENT)
        })
        .map(render_filter)
        .collect();
    ours.sort();
    writeln!(output, "filters: {}", ours.len()).unwrap();
    for filter in ours {
        output.push_str(&filter);
    }

    Ok(output)
}

// ---------------------------------------------------------------------------
// Rendering
// ---------------------------------------------------------------------------

fn render_provider(provider: &OwnedProvider) -> String {
    format!(
        "provider {} | flags {} | {}\n",
        render_guid(provider.key),
        provider.flags,
        display_data(&provider.name, &provider.description),
    )
}

fn render_sublayer(sublayer: &OwnedSublayer) -> String {
    format!(
        "sublayer {} | weight {} | flags {} | {}\n",
        render_guid(sublayer.key),
        sublayer.weight,
        sublayer.flags,
        display_data(&sublayer.name, &sublayer.description),
    )
}

/// `FWPM_FILTER_FLAG_INDEXED`: set by the engine according to its own indexing
/// heuristics, not by the caller. The same filter is indexed or not depending
/// on the engine's state at add time, so it is not part of the snapshot.
const FLAG_INDEXED: u32 = 0x40;

fn render_filter(filter: &OwnedFilter) -> String {
    let mut out = format!(
        "filter {} | {} | layer {} | sublayer {} | action {} | weight {} | flags {}\n",
        // The endpoint rules let the engine generate their key; everything else
        // has a fixed one. A name is shown for known keys, `<auto>` otherwise.
        render_filter_key(filter.key),
        display_data(&filter.name, &filter.description),
        layer_name(filter.layer),
        render_guid(filter.sublayer),
        if filter.action == FWP_ACTION_PERMIT {
            "PERMIT"
        } else {
            "BLOCK"
        },
        render_weight(&filter.weight),
        filter.flags & !FLAG_INDEXED,
    );

    let mut conditions: Vec<String> = filter.conditions.iter().map(render_condition).collect();
    conditions.sort();
    for condition in conditions {
        writeln!(out, "    {condition}").unwrap();
    }
    out
}

/// Render a display data pair as `"name" / "description"`.
fn display_data(name: &str, description: &str) -> String {
    format!("{name:?} / {description:?}")
}

/// Render a GUID: by name if it is one of the firewall's fixed GUIDs, else in
/// the canonical form.
fn render_guid(guid: wfp::Guid) -> String {
    if let Some(name) = known_object_name(&guid) {
        return name.to_owned();
    }
    format!("{guid:?}")
}

/// Render a filter key: known GUIDs by name, anything else as `<auto>`, since
/// the engine generates the keys of the endpoint rules fresh on every apply.
fn render_filter_key(guid: wfp::Guid) -> String {
    if let Some(name) = known_object_name(&guid) {
        return name.to_owned();
    }
    "<auto>".to_owned()
}

/// Render a layer GUID as its well-known name, if any.
fn layer_name(guid: wfp::Guid) -> String {
    use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform as wfp_sys;
    let name = if guid == wfp::Guid::from(wfp_sys::FWPM_LAYER_ALE_AUTH_CONNECT_V4) {
        "ALE_AUTH_CONNECT_V4"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_LAYER_ALE_AUTH_CONNECT_V6) {
        "ALE_AUTH_CONNECT_V6"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_LAYER_ALE_AUTH_RECV_ACCEPT_V4) {
        "ALE_AUTH_RECV_ACCEPT_V4"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_LAYER_ALE_AUTH_RECV_ACCEPT_V6) {
        "ALE_AUTH_RECV_ACCEPT_V6"
    } else {
        return render_guid(guid);
    };
    name.to_owned()
}

/// Condition field names, for readable snapshots. Falls back to the GUID.
fn condition_field_name(guid: wfp::Guid) -> String {
    use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform as wfp_sys;
    let name = if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_IP_REMOTE_ADDRESS) {
        "IP_REMOTE_ADDRESS"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_IP_LOCAL_ADDRESS) {
        "IP_LOCAL_ADDRESS"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_IP_REMOTE_PORT) {
        "IP_REMOTE_PORT"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_IP_LOCAL_PORT) {
        "IP_LOCAL_PORT"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_IP_PROTOCOL) {
        "IP_PROTOCOL"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_ALE_APP_ID) {
        "ALE_APP_ID"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_IP_LOCAL_INTERFACE) {
        "IP_LOCAL_INTERFACE"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_FLAGS) {
        "FLAGS"
    } else if guid == wfp::Guid::from(wfp_sys::FWPM_CONDITION_INTERFACE_TYPE) {
        "INTERFACE_TYPE"
    } else {
        return render_guid(guid);
    };
    name.to_owned()
}

/// Render the weight of a filter: a weight class (u8), or a raw value.
fn render_weight(weight: &OwnedWeight) -> String {
    match weight {
        OwnedWeight::Auto => "auto".to_owned(),
        OwnedWeight::Class(class) => format!("class:{class}"),
        OwnedWeight::RawU64(value) => format!("raw:{value}"),
        OwnedWeight::RawU32(value) => format!("raw:{value}"),
        OwnedWeight::Other(other) => format!("unhandled-type:{other}"),
    }
}

/// How the tunnel interface is rendered.
const TUNNEL_ALIAS_PLACEHOLDER: &str = "alias:<tunnel>";

/// Render a single filter condition.
fn render_condition(condition: &OwnedCondition) -> String {
    // Interface LUIDs are rendered as the alias they resolve to, so that they
    // are stable across machines and boots.
    let value = if condition.field
        == wfp::Guid::from(
            windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform::FWPM_CONDITION_IP_LOCAL_INTERFACE,
        )
        && let OwnedValue::U64(luid) = condition.value
    {
        format!("luid:{}", render_luid(luid))
    } else {
        render_value(&condition.value)
    };

    format!(
        "{} {} {}",
        condition_field_name(condition.field),
        render_match_type(condition.match_type),
        value,
    )
}

fn render_match_type(match_type: i32) -> &'static str {
    use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform as wfp_sys;
    match match_type {
        x if x == wfp_sys::FWP_MATCH_EQUAL => "==",
        x if x == wfp_sys::FWP_MATCH_GREATER => ">",
        x if x == wfp_sys::FWP_MATCH_GREATER_OR_EQUAL => ">=",
        x if x == wfp_sys::FWP_MATCH_LESS => "<",
        x if x == wfp_sys::FWP_MATCH_LESS_OR_EQUAL => "<=",
        x if x == wfp_sys::FWP_MATCH_RANGE => "inside",
        x if x == wfp_sys::FWP_MATCH_FLAGS_ALL_SET => "flags-all-set",
        x if x == wfp_sys::FWP_MATCH_FLAGS_ANY_SET => "flags-any-set",
        x if x == wfp_sys::FWP_MATCH_FLAGS_NONE_SET => "flags-none-set",
        x if x == wfp_sys::FWP_MATCH_EQUAL_CASE_INSENSITIVE => "==nocase",
        x if x == wfp_sys::FWP_MATCH_NOT_EQUAL => "!=",
        _ => "match-type?",
    }
}

/// Render a condition value, normalizing everything that can vary between runs.
fn render_value(value: &OwnedValue) -> String {
    match value {
        OwnedValue::Empty => "<empty>".to_owned(),
        OwnedValue::U8(value) => format!("u8:{value}"),
        OwnedValue::U16(value) => format!("u16:{value}"),
        OwnedValue::U32(value) => format!("u32:{value}"),
        OwnedValue::U64(value) => format!("u64:{value}"),
        OwnedValue::I8(value) => format!("i8:{value}"),
        OwnedValue::I16(value) => format!("i16:{value}"),
        OwnedValue::I32(value) => format!("i32:{value}"),
        OwnedValue::I64(value) => format!("i64:{value}"),
        OwnedValue::ByteArray16(bytes) => {
            let addr = Ipv6Addr::from(*bytes);
            format!("ba16:{addr}")
        }
        OwnedValue::ByteBlob(data) => {
            // The blob holds a device path. It is UTF-16 when every second
            // byte is zero or part of a valid code point, else raw bytes.
            let mut text = if data.len() % 2 == 0 && data.iter().skip(1).step_by(2).all(|b| *b == 0)
            {
                String::from_utf16_lossy(
                    &data
                        .chunks_exact(2)
                        .take_while(|c| !(c[0] == 0 && c[1] == 0))
                        .map(|c| u16::from_le_bytes([c[0], c[1]]))
                        .collect::<Vec<_>>(),
                )
            } else {
                data.iter()
                    .take_while(|b| **b != 0)
                    .map(|b| *b as char)
                    .collect::<String>()
            };
            // The volume number in a device path differs between machines and
            // boots: normalize it away.
            normalize_volume(&mut text);
            format!("app:{text}")
        }
        OwnedValue::V4Mask { addr, mask } => format!("v4:{}", render_v4_and_mask(*addr, *mask)),
        OwnedValue::V6Mask { addr, prefix } => {
            let addr = Ipv6Addr::from(*addr);
            format!("v6:{addr}/{prefix}")
        }
        OwnedValue::Range { low, high } => {
            format!("range:[{}, {}]", render_scalar(low), render_scalar(high))
        }
        OwnedValue::UnicodeString(string) => format!("str:{string:?}"),
        OwnedValue::Opaque(kind) => (*kind).to_owned(),
        OwnedValue::Unknown(kind) => format!("value-type?:{kind}"),
    }
}

fn render_scalar(value: &OwnedScalar) -> String {
    match value {
        OwnedScalar::U8(value) => format!("u8:{value}"),
        OwnedScalar::U16(value) => format!("u16:{value}"),
        OwnedScalar::U32(value) => format!("u32:{value}"),
        OwnedScalar::U64(value) => format!("u64:{value}"),
        OwnedScalar::Unknown(kind) => format!("value-type?:{kind}"),
    }
}

/// Render a v4 address and mask in CIDR form, given they are both in the
/// "first octet in the most significant byte" representation WFP uses.
fn render_v4_and_mask(addr: u32, mask: u32) -> String {
    let prefix = mask.count_ones();
    let octets = Ipv4Addr::from(addr.to_be_bytes());
    format!("{octets}/{prefix}")
}

/// Replace `harddiskvolumeN` with `harddiskvolumeX` in an application path.
fn normalize_volume(path: &mut String) {
    if let Some(start) = path.find("harddiskvolume") {
        let digits_start = start + "harddiskvolume".len();
        let digits_end = path[digits_start..]
            .find(|c: char| !c.is_ascii_digit())
            .map(|end| digits_start + end)
            .unwrap_or(path.len());
        path.replace_range(digits_start..digits_end, "X");
    }
}

/// Render a local interface LUID as the alias it resolves to, e.g.
/// `alias:Ethernet`. The tunnel interface, which differs between machines, is
/// rendered as `alias:<tunnel>`.
fn render_luid(luid: u64) -> String {
    const MAX_ALIAS_LEN: u32 = 256;
    let mut alias = [0u16; MAX_ALIAS_LEN as usize];
    // SAFETY: `alias` is a valid buffer of `MAX_ALIAS_LEN` wide characters.
    let status = unsafe {
        ConvertInterfaceLuidToAlias(
            &NET_LUID_LH { Value: luid },
            alias.as_mut_ptr(),
            MAX_ALIAS_LEN as usize,
        )
    };
    if status == ERROR_SUCCESS {
        let len = alias.iter().position(|c| *c == 0).unwrap_or(alias.len());
        let alias = String::from_utf16_lossy(&alias[..len]);
        if alias == super::tunnel_alias() {
            TUNNEL_ALIAS_PLACEHOLDER.to_owned()
        } else {
            format!("alias:{alias}")
        }
    } else {
        format!("0x{luid:x}")
    }
}

// ---------------------------------------------------------------------------
// Copying WFP objects into owned types
// ---------------------------------------------------------------------------

/// Read a null-terminated wide string. The pointer is only read, never stored.
unsafe fn pwstr_to_string(string: windows_sys::core::PWSTR) -> String {
    if string.is_null() {
        return String::new();
    }
    let mut len = 0usize;
    // SAFETY: the caller guarantees the string is null-terminated and valid.
    while unsafe { *string.add(len) } != 0 {
        len += 1;
    }
    // SAFETY: `len` characters, all valid.
    String::from_utf16_lossy(unsafe { std::slice::from_raw_parts(string, len) })
}

unsafe fn copy_weight(
    weight: &windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform::FWP_VALUE0,
) -> OwnedWeight {
    use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform as wfp_sys;
    // SAFETY: the union is only read from the variant given by `r#type`.
    unsafe {
        match weight.r#type {
            FWP_EMPTY => OwnedWeight::Auto,
            wfp_sys::FWP_UINT8 => OwnedWeight::Class(weight.Anonymous.uint8),
            wfp_sys::FWP_UINT32 => OwnedWeight::RawU32(weight.Anonymous.uint32),
            wfp_sys::FWP_UINT64 => OwnedWeight::RawU64(*weight.Anonymous.uint64),
            other => OwnedWeight::Other(other),
        }
    }
}

unsafe fn copy_scalar(
    value: &windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform::FWP_VALUE0,
) -> OwnedScalar {
    use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform as wfp_sys;
    // SAFETY: the union is only read from the variant given by `r#type`.
    unsafe {
        match value.r#type {
            wfp_sys::FWP_UINT8 => OwnedScalar::U8(value.Anonymous.uint8),
            wfp_sys::FWP_UINT16 => OwnedScalar::U16(value.Anonymous.uint16),
            wfp_sys::FWP_UINT32 => OwnedScalar::U32(value.Anonymous.uint32),
            wfp_sys::FWP_UINT64 => OwnedScalar::U64(*value.Anonymous.uint64),
            other => OwnedScalar::Unknown(other),
        }
    }
}

unsafe fn copy_condition_value(
    value: &windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform::FWP_CONDITION_VALUE0,
) -> OwnedValue {
    use windows_sys::Win32::NetworkManagement::WindowsFilteringPlatform as wfp_sys;

    // SAFETY: the union is only read from the variant given by `r#type`, and
    // everything read from it is copied while the engine memory is valid.
    unsafe {
        match value.r#type {
            FWP_EMPTY => OwnedValue::Empty,
            wfp_sys::FWP_UINT8 => OwnedValue::U8(value.Anonymous.uint8),
            wfp_sys::FWP_UINT16 => OwnedValue::U16(value.Anonymous.uint16),
            wfp_sys::FWP_UINT32 => OwnedValue::U32(value.Anonymous.uint32),
            wfp_sys::FWP_UINT64 => OwnedValue::U64(*value.Anonymous.uint64),
            wfp_sys::FWP_INT8 => OwnedValue::I8(value.Anonymous.int8),
            wfp_sys::FWP_INT16 => OwnedValue::I16(value.Anonymous.int16),
            wfp_sys::FWP_INT32 => OwnedValue::I32(value.Anonymous.int32),
            wfp_sys::FWP_INT64 => OwnedValue::I64(*value.Anonymous.int64),
            wfp_sys::FWP_FLOAT | wfp_sys::FWP_DOUBLE => OwnedValue::Opaque("float"),
            wfp_sys::FWP_BYTE_ARRAY16_TYPE => {
                let array = value.Anonymous.byteArray16;
                if array.is_null() {
                    OwnedValue::Opaque("<ba16:null>")
                } else {
                    OwnedValue::ByteArray16((*array).byteArray16)
                }
            }
            FWP_BYTE_BLOB_TYPE => {
                let blob = value.Anonymous.byteBlob;
                if blob.is_null() {
                    OwnedValue::Opaque("<blob:null>")
                } else {
                    OwnedValue::ByteBlob(
                        std::slice::from_raw_parts((*blob).data, (*blob).size as usize).to_vec(),
                    )
                }
            }
            FWP_V4_ADDR_MASK => {
                let addr_mask = value.Anonymous.v4AddrMask;
                if addr_mask.is_null() {
                    OwnedValue::Opaque("<v4:null>")
                } else {
                    OwnedValue::V4Mask {
                        addr: (*addr_mask).addr,
                        mask: (*addr_mask).mask,
                    }
                }
            }
            FWP_V6_ADDR_MASK => {
                let addr_mask = value.Anonymous.v6AddrMask;
                if addr_mask.is_null() {
                    OwnedValue::Opaque("<v6:null>")
                } else {
                    OwnedValue::V6Mask {
                        addr: (*addr_mask).addr,
                        prefix: (*addr_mask).prefixLength,
                    }
                }
            }
            FWP_RANGE_TYPE => {
                let range = value.Anonymous.rangeValue;
                if range.is_null() {
                    OwnedValue::Opaque("<range:null>")
                } else {
                    OwnedValue::Range {
                        low: copy_scalar(&(*range).valueLow),
                        high: copy_scalar(&(*range).valueHigh),
                    }
                }
            }
            FWP_UNICODE_STRING_TYPE => {
                OwnedValue::UnicodeString(pwstr_to_string(value.Anonymous.unicodeString))
            }
            FWP_TOKEN_INFORMATION_TYPE | FWP_TOKEN_ACCESS_INFORMATION_TYPE => {
                OwnedValue::Opaque("token")
            }
            FWP_SID => OwnedValue::Opaque("sid"),
            FWP_SECURITY_DESCRIPTOR_TYPE => OwnedValue::Opaque("sd"),
            other => OwnedValue::Unknown(other),
        }
    }
}

unsafe fn copy_provider(provider: &FWPM_PROVIDER0) -> OwnedProvider {
    // SAFETY: the strings and provider key are valid for the enumeration.
    unsafe {
        OwnedProvider {
            key: wfp::Guid::from(provider.providerKey),
            name: pwstr_to_string(provider.displayData.name),
            description: pwstr_to_string(provider.displayData.description),
            flags: provider.flags,
        }
    }
}

unsafe fn copy_sublayer(sublayer: &FWPM_SUBLAYER0) -> OwnedSublayer {
    // SAFETY: the strings and sublayer key are valid for the enumeration.
    unsafe {
        OwnedSublayer {
            key: wfp::Guid::from(sublayer.subLayerKey),
            name: pwstr_to_string(sublayer.displayData.name),
            description: pwstr_to_string(sublayer.displayData.description),
            weight: sublayer.weight,
            flags: sublayer.flags,
        }
    }
}

unsafe fn copy_filter(filter: &FWPM_FILTER0) -> OwnedFilter {
    // SAFETY: all of the filter's memory, including its conditions, is valid
    // for the enumeration.
    unsafe {
        let conditions = (0..filter.numFilterConditions)
            .map(|i| {
                let condition = &*filter.filterCondition.add(i as usize);
                OwnedCondition {
                    field: wfp::Guid::from(condition.fieldKey),
                    match_type: condition.matchType,
                    value: copy_condition_value(&condition.conditionValue),
                }
            })
            .collect();

        OwnedFilter {
            key: wfp::Guid::from(filter.filterKey),
            name: pwstr_to_string(filter.displayData.name),
            description: pwstr_to_string(filter.displayData.description),
            layer: wfp::Guid::from(filter.layerKey),
            sublayer: wfp::Guid::from(filter.subLayerKey),
            provider: if filter.providerKey.is_null() {
                None
            } else {
                Some(wfp::Guid::from(*filter.providerKey))
            },
            action: filter.action.r#type,
            flags: filter.flags,
            weight: copy_weight(&filter.weight),
            conditions,
        }
    }
}

// ---------------------------------------------------------------------------
// Enumeration
// ---------------------------------------------------------------------------

/// Open a session against the filter engine, used only to read state.
fn open_session() -> Result<HANDLE, DumpError> {
    let mut session: HANDLE = ptr::null_mut();
    // SAFETY: `FwpmEngineOpen0` with null arguments is the documented way of
    // opening a session; no session flags are needed for read-only enumeration.
    let status = unsafe {
        FwpmEngineOpen0(
            ptr::null_mut(),
            RPC_C_AUTHN_DEFAULT as u32,
            ptr::null_mut(),
            ptr::null(),
            &raw mut session,
        )
    };
    check(status)?;
    if session.is_null() {
        return Err(DumpError(ERROR_SUCCESS));
    }
    Ok(session)
}

/// Number of objects fetched per enumeration call.
const ENUM_BATCH: u32 = 100;

/// Enumerate objects with the `Fwpm*Enum0` family: fetch batches of pointers,
/// copy every object into owned types, free the batch, repeat.
///
/// `copy` must deep-copy everything it needs from the object; the batch (and
/// with it the object memory) is freed immediately afterwards.
unsafe fn enumerate_objects<T, Owned>(
    create_handle: impl Fn(HANDLE, &mut HANDLE) -> u32,
    destroy_handle: impl Fn(HANDLE, HANDLE) -> u32,
    fetch: impl Fn(HANDLE, HANDLE, u32, &mut *mut *mut T, &mut u32) -> u32,
    copy: unsafe fn(&T) -> Owned,
) -> Result<Vec<Owned>, DumpError> {
    let session = open_session()?;

    let mut enum_handle: HANDLE = ptr::null_mut();
    // SAFETY: a null template enumerates every object of the type.
    let status = create_handle(session, &mut enum_handle);
    if let Err(error) = check(status) {
        // SAFETY: the session handle is valid and only closed here.
        unsafe { FwpmEngineClose0(session) };
        return Err(error);
    }

    let mut objects = Vec::new();
    let result = (|| {
        loop {
            let mut entries: *mut *mut T = ptr::null_mut();
            let mut num_entries = 0u32;
            // SAFETY: the engine and enumeration handles are valid.
            let status = fetch(
                session,
                enum_handle,
                ENUM_BATCH,
                &mut entries,
                &mut num_entries,
            );
            check(status)?;
            if num_entries == 0 {
                return Ok(());
            }
            for index in 0..num_entries as usize {
                // SAFETY: `num_entries` pointers are valid until
                // `FwpmFreeMemory0`, and each pointer targets a valid object.
                objects.push(unsafe { copy(&*entries.add(index).read()) });
            }
            // SAFETY: the entries pointer came from the enumeration call above.
            unsafe { FwpmFreeMemory0(ptr::from_mut(&mut entries).cast()) };
            if num_entries < ENUM_BATCH {
                return Ok(());
            }
        }
    })();

    // SAFETY: the enumeration handle is valid and only destroyed here.
    destroy_handle(session, enum_handle);
    // SAFETY: the session handle is valid and only closed here.
    unsafe { FwpmEngineClose0(session) };
    result?;
    Ok(objects)
}

fn enumerate_providers() -> Result<Vec<OwnedProvider>, DumpError> {
    // SAFETY: the wrapped raw WFP calls only run while the session handle is
    // open, and `copy_provider` only reads the enumerated provider.
    unsafe {
        enumerate_objects(
            |engine, handle| FwpmProviderCreateEnumHandle0(engine, ptr::null(), handle),
            |engine, handle| {
                // SAFETY: called with the open session and enumeration handles.
                FwpmProviderDestroyEnumHandle0(engine, handle)
            },
            |engine, handle, batch, entries, count| {
                // SAFETY: called with the open session and enumeration handles.
                FwpmProviderEnum0(engine, handle, batch, entries, count)
            },
            copy_provider,
        )
    }
}

fn enumerate_sublayers() -> Result<Vec<OwnedSublayer>, DumpError> {
    // SAFETY: the wrapped raw WFP calls only run while the session handle is
    // open, and `copy_sublayer` only reads the enumerated sublayer.
    unsafe {
        enumerate_objects(
            |engine, handle| FwpmSubLayerCreateEnumHandle0(engine, ptr::null(), handle),
            |engine, handle| {
                // SAFETY: called with the open session and enumeration handles.
                FwpmSubLayerDestroyEnumHandle0(engine, handle)
            },
            |engine, handle, batch, entries, count| {
                // SAFETY: called with the open session and enumeration handles.
                FwpmSubLayerEnum0(engine, handle, batch, entries, count)
            },
            copy_sublayer,
        )
    }
}

fn enumerate_filters() -> Result<Vec<OwnedFilter>, DumpError> {
    // SAFETY: the wrapped raw WFP calls only run while the session handle is
    // open, and `copy_filter` only reads the enumerated filter and its
    // conditions.
    unsafe {
        enumerate_objects(
            |engine, handle| FwpmFilterCreateEnumHandle0(engine, ptr::null(), handle),
            |engine, handle| {
                // SAFETY: called with the open session and enumeration handles.
                FwpmFilterDestroyEnumHandle0(engine, handle)
            },
            |engine, handle, batch, entries, count| {
                // SAFETY: called with the open session and enumeration handles.
                FwpmFilterEnum0(engine, handle, batch, entries, count)
            },
            copy_filter,
        )
    }
}
